import{_ as a,o as t,c as r,al as o}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"Arm, Disarm, Prearm Конфігурація","description":"","frontmatter":{},"headers":[],"relativePath":"uk/advanced_config/prearm_arm_disarm.md","filePath":"uk/advanced_config/prearm_arm_disarm.md"}'),i={name:"uk/advanced_config/prearm_arm_disarm.md"};function s(n,e,l,d,m,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="arm-disarm-prearm-конфігурація" tabindex="-1">Arm, Disarm, Prearm Конфігурація <a class="header-anchor" href="#arm-disarm-prearm-конфігурація" aria-label="Permalink to &quot;Arm, Disarm, Prearm Конфігурація&quot;">​</a></h1><p>Транспортні засоби можуть мати рухомі частини, деякі з яких можуть бути потенційно небезпечними під час роботи (особливо мотори та пропелери)!</p><p>Для зменшення ймовірності аварій, PX4 має явні стани для включення компонентів транспортного засобу:</p><ul><li><strong>Вимкнено:</strong> Немає живлення для моторів або приводів.</li><li><strong>Передпускний стан:</strong> Мотори/пропелери заблоковані, але приводи для не небезпечної електроніки живлені (наприклад, елерони, закрилки і т. д.).</li><li><strong>Озброєно:</strong> Транспортний засіб повністю увімкнено. Двигуни/пропелери можуть обертатися (небезпечно!)</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Наземні станції можуть відображати <em>вимкнено</em> для транспортних засобів у режимі передпуску. Хоча це не є технічно правильним для транспортних засобів у режимі передпуску, це &quot;безпечно&quot;.</p></div><p>Користувачі можуть керувати переходом між цими станами, використовуючи <a href="./../getting_started/px4_basic_concepts#safety-switch">захисний перемикач</a> на транспортному засобі (за бажанням) <em>та</em> перемикач/кнопку <a href="#arm_disarm_switch">озброєння</a>, <a href="#arm_disarm_gestures">жест озброєння</a> або <em>команду MAVLink</em> на наземному контролері:</p><ul><li><p>A <em>safety switch</em> is a control <em>on the vehicle</em> that must be engaged before the vehicle can be armed, and which may also prevent pre-arming (depending on the configuration). Зазвичай захисний перемикач інтегровано у блок GPS, але він також може бути окремим фізичним компонентом.</p><p>Транспортний засіб, який озброєний, потенційно небезпечний. Захисний перемикач - це додатковий механізм, який запобігає випадковому озброєнню.</p></li></ul><p>:::</p><ul><li><p>Перемикач <em>озброєння</em> - це перемикач або кнопка <em>на пульті керування RC</em>, який може бути використаний для озброєння транспортного засобу та запуску моторів (якщо озброєння не заборонене захисним перемикачем).</p></li><li><p>Жест озброєння - це рух педалей <em>на пульті керування RC</em>, який може бути використаний як альтернатива перемикачу озброєння.</p></li><li><p>MAVLink commands can also be sent by a ground control station to pre-arm, arm, or disarm a vehicle.</p></li></ul><p>PX4 також автоматично вимикає транспортний засіб, якщо він не злітає протягом певного часу після озброєння, і якщо він не вимикається вручну після посадки. Це зменшує час, коли на землі знаходиться озброєний (і, отже, небезпечний) транспортний засіб.</p><p>PX4 дозволяє налаштовувати роботу передпуску, озброєння та вимикання за допомогою параметрів (які можна редагувати в <em>QGroundControl</em> за допомогою <a href="./../advanced_config/parameters">редактора параметрів</a>), як описано у наступних розділах.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Параметри озброєння/вимикання можна знайти у <a href="./../advanced_config/parameter_reference#commander">Посилання на параметри &gt; Командир</a> (шукайте <code>COM_ARM_*</code> та <code>COM_DISARM_*</code>).</p></div><h2 id="arm_disarm_gestures" tabindex="-1">Arming/Disarming Gestures <a class="header-anchor" href="#arm_disarm_gestures" aria-label="Permalink to &quot;Arming/Disarming Gestures {#arm_disarm_gestures}&quot;">​</a></h2><p>За замовчуванням, транспортний засіб озброюється та вимикається шляхом виконання певних рухів педалями газу/рулем в маневрів та утримання їх протягом 1 секунди.</p><ul><li><strong>Озброєння:</strong> Мінімальна педаль газу, максимальний рульовий вектор</li><li><strong>Вимикання:</strong> Мінімальна педаль газу, мінімальний рульовий вектор</li></ul><p>RC controllers will use different sticks for throttle and yaw <a href="./../getting_started/rc_transmitter_receiver#types-of-remote-controllers">based on their mode</a>, and hence different gestures:</p><ul><li><strong>Режим 2</strong>: <ul><li><em>Озброєння:</em> Ліва педаль вниз і вправо.</li><li><em>Вимкнення:</em> Ліва педаль вниз і вліво.</li></ul></li><li><strong>Режим 1</strong>: <ul><li><em>Озброєння:</em> Ліва педаль вправо, права педаль вниз.</li><li><em>Вимкнення:</em> Ліва педаль вліво, права педаль вниз.</li></ul></li></ul><p>Note that disarming in any altitude controlled mode is only possible after landing was detected. In manually piloted modes without altitude control, such as Stabilized, Acro, and Manual, it&#39;s always possible to disarm using gestures or buttons — even in flight.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="MAN_ARM_GESTURE"></a><a href="./../advanced_config/parameter_reference#MAN_ARM_GESTURE">MAN_ARM_GESTURE</a></td><td>Enable arm/disarm stick guesture. <code>0</code>: Disabled, <code>1</code>: Enabled (default).</td></tr></tbody></table><h2 id="arm_disarm_switch" tabindex="-1">Arming Button/Switch <a class="header-anchor" href="#arm_disarm_switch" aria-label="Permalink to &quot;Arming Button/Switch {#arm_disarm_switch}&quot;">​</a></h2><p>Кнопку <em>озброєння</em> або &quot;моментальний перемикач&quot; можна налаштувати для спрацьовування озброєння/вимикання <em>замість</em> <a href="#arm_disarm_gestures">озброєння за допомогою жестів</a> (встановлення перемикача озброєння вимикає озброєння за допомогою жестів). The button should be held down for one second to arm (when disarmed) or disarm (when armed).</p><p>Двопозиційний перемикач також може використовуватися для озброєння/вимикання, при цьому відповідні команди на озброєння/вимкнення надсилаються при <em>перемиканні</em> перемикача.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Двопозиційні перемикачі для озброєння переважно використовуються в/рекомендовані для гоночних дронів.</p></div><p>Перемикач або кнопка призначається (та активується) за допомогою <a href="#RC_MAP_ARM_SW">RC_MAP_ARM_SW</a>, а тип перемикача налаштовується за допомогою <a href="#COM_ARM_SWISBTN">COM_ARM_SWISBTN</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="RC_MAP_ARM_SW"></a><a href="./../advanced_config/parameter_reference#RC_MAP_ARM_SW">RC_MAP_ARM_SW</a></td><td>Канал перемикача озброєння радіокерування (типове значення: 0 - не призначено). Якщо визначено, вказаний канал радіокерування (кнопка/перемикач) використовується для озброєння замість жесту палиці. <br><strong>Note:</strong><br>- This setting <em>disables the stick gesture</em>!<br>- This setting applies to RC controllers. It does not apply to Joystick controllers that are connected via <em>QGroundControl</em>.</td></tr><tr><td><a id="COM_ARM_SWISBTN"></a><a href="./../advanced_config/parameter_reference#COM_ARM_SWISBTN">COM_ARM_SWISBTN</a></td><td>Перемикач озброєння є моментальною кнопкою. <br>- <code>0</code>: Arm switch is a 2-position switch where arm/disarm commands are sent on switch transitions.<br>-<code>1</code>: Arm switch is a momentary button where the arm/disarm command is sent after holding down the button for one second.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Перемикач також можна налаштувати як частину конфігурації <em>QGroundControl</em> для <a href="./../config/flight_mode">Режиму польоту</a>.</p></div><h2 id="автоматичне-вимкнення" tabindex="-1">Автоматичне вимкнення <a class="header-anchor" href="#автоматичне-вимкнення" aria-label="Permalink to &quot;Автоматичне вимкнення&quot;">​</a></h2><p>За замовчуванням транспортні засоби автоматично вимикаються при посадці або якщо ви заберете занадто багато часу, щоб злітати після озброєння. Ця функція налаштовується за допомогою наступних таймаутів.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="COM_DISARM_LAND"></a><a href="./../advanced_config/parameter_reference#COM_DISARM_LAND">COM_DISARM_LAND</a></td><td>Час очікування для автоматичного відбрасування після приземлення. За замовчуванням: 2с (значення -1, щоб вимкнути).</td></tr><tr><td><a id="COM_DISARM_PRFLT"></a><a href="./../advanced_config/parameter_reference#COM_DISARM_PRFLT">COM_DISARM_PRFLT</a></td><td>Час очікування для автоматичного відбрасування, якщо занадто повільно підйом. Default: 10s (-1 to disable).</td></tr></tbody></table><p>By default, the vehicle keeps safety off after disarming. If <a href="#COM_FORCE_SAFETY">COM_FORCE_SAFETY</a> is set to <code>1</code>, safety is re-enabled on disarm, so it must be turned off again (by switch or MAVLink command, depending on <a href="#COM_SAFETY_MODE">COM_SAFETY_MODE</a>) before the next arming. In modes that pre-arm when safety is turned off, this also exits the pre-armed state. This parameter has no effect when <code>COM_SAFETY_MODE</code> is set to <code>0</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="COM_FORCE_SAFETY"></a><a href="./../advanced_config/parameter_reference#COM_FORCE_SAFETY">COM_FORCE_SAFETY</a></td><td>Re-enable safety when the vehicle disarms. Default: <code>0</code> (Disabled).</td></tr></tbody></table><h2 id="auto-arming-on-boot" tabindex="-1">Auto-Arming on Boot <a class="header-anchor" href="#auto-arming-on-boot" aria-label="Permalink to &quot;Auto-Arming on Boot&quot;">​</a></h2><p>The vehicle can be configured to arm automatically on boot once all preflight checks pass, using the <code>COM_ARM_ON_BOOT</code> parameter. For safety, PX4 enforces a minimum 5-second delay after boot before attempting to arm.</p><p>Once armed this way, the vehicle will not re-arm automatically after a manual disarm.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The parameter value is read once at boot. Changing it while the system is running has no effect until the next reboot.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Use with caution. A vehicle that arms automatically can spin up motors and actuators without any operator gesture. Ensure the vehicle is in a safe state before powering on.</p></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="COM_ARM_ON_BOOT"></a><a href="./../advanced_config/parameter_reference#COM_ARM_ON_BOOT">COM_ARM_ON_BOOT</a></td><td>Arm automatically once preflight checks pass after boot. Default: <code>0</code> (Disabled).</td></tr></tbody></table><h2 id="prearm_checks" tabindex="-1">Pre-Arm Checks <a class="header-anchor" href="#prearm_checks" aria-label="Permalink to &quot;Pre-Arm Checks {#prearm_checks}&quot;">​</a></h2><p>To reduce accidents, vehicles are only allowed to arm certain conditions are met (some of which are configurable). Армування заборонено у таких випадках:</p><ul><li>Повітряне судно не перебуває у &quot;здоровому&quot; стані. Наприклад, воно не калібрується або має помилки датчиків.</li><li>The vehicle still has its <a href="#safety_state">safety state</a> set to <em>ON</em>. This could for instance be a <a href="./../getting_started/px4_basic_concepts#safety-switch">safety switch</a> that has not been engaged.</li><li>The vehicle has a <a href="./../peripherals/remote_id">remote ID</a> that is unhealthy or otherwise not ready</li><li>VTOL-повітряне судно перебуває в режимі фіксованого крила (<a href="./../advanced_config/parameter_reference#CBRK_VTOLARMING">by default(за замовчуванням)</a>).</li><li>Поточний режим потребує належної глобальної позиційної оцінки, але повітряне судно не має блокування GPS.</li><li>Many more (see <a href="./../config/safety#arming-disarming-settings">arming/disarming safety settings</a> for more information).</li></ul><p>The current failed checks can be viewed in QGroundControl (v4.2.0 and later) <a href="./../flying/pre_flight_checks#qgc-arming-check-report">Arming Check Report</a> (see also <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/fly_view/fly_view_toolbar.html#flight-status" target="_blank" rel="noreferrer">Fly View &gt; Toolbar &gt; Flight Status</a>).</p><p>Зауважте, що внутрішньо PX4 перевіряє активацію на 10 Гц. Список невдалих перевірок зберігається, і якщо цей список змінюється, PX4 видає поточний список за допомогою <a href="./../concept/events_interface">інтерфейсу подій</a>. Список також надсилається, коли GCS підключається. Effectively the GCS knows the status of pre-arm checks immediately, both when disarmed and armed.</p><details class="details custom-block"><summary>Details</summary><p>Implementation notes for developers Примітки для розробників Реалізація клієнта знаходиться у <a href="https://github.com/mavlink/libevents" target="_blank" rel="noreferrer">libevents</a>:</p><ul><li><a href="https://github.com/mavlink/libevents#event-groups" target="_blank" rel="noreferrer">libevents &gt; Групи подій</a></li><li><a href="https://github.com/mavlink/libevents/blob/main/libs/cpp/parse/health_and_arming_checks.h" target="_blank" rel="noreferrer">health_and_arming_checks.h</a></li></ul><p>QGC реалізація: <a href="https://github.com/mavlink/qgroundcontrol/blob/master/src/MAVLink/LibEvents/HealthAndArmingCheckReport.cc" target="_blank" rel="noreferrer">HealthAndArmingCheckReport.cc</a>.</p></details><p>PX4 також видає підмножину інформації перевірки постановки на охорону в повідомленні <a href="https://mavlink.io/en/messages/common.html#SYS_STATUS" target="_blank" rel="noreferrer">SYS_STATUS</a> (див. <a href="https://mavlink.io/en/messages/common.html#MAV_SYS_STATUS_SENSOR" target="_blank" rel="noreferrer">MAV_SYS_STATUS_SENSOR</a>).</p><h2 id="safety_state" tabindex="-1">Arming Sequence: Safety State <a class="header-anchor" href="#safety_state" aria-label="Permalink to &quot;Arming Sequence: Safety State {#safety_state}&quot;">​</a></h2><p>The arming sequence depends on whether or not there is a <em>safety switch</em>, and is controlled by the parameter <a href="#COM_SAFETY_MODE">COM_SAFETY_MODE</a>. Changes to the parameter only take effect after a reboot.</p><p>When disarmed (or pre-armed), the safety state can either be <em>ON</em> (a.k.a. <em>SAFE</em>), or <em>OFF</em> (a.k.a. <em>DANGEROUS</em>). When it is <em>ON</em>, arming will always be prevented. When it is <em>OFF</em>, the vehicle can be armed for as long as the <a href="#prearm_checks">pre-arm checks</a> have passed.</p><p>Additionally, the <a href="#COM_PREARM_MODE">COM_PREARM_MODE</a> parameter defines when/if pre-arm mode is enabled (&quot;safe&quot;/non-throttling actuators are able to move):</p><ul><li><code>Disabled</code> (Default): Pre-arm mode disabled (there is no stage where only non-throttling actuators are enabled).</li><li><code>When safety off</code>: Pre-arm mode is enabled when safety is turned off.</li><li><code>Always</code>: Pre-arm mode is enabled from power up.</li></ul><p>The sections below detail the startup sequences for the different configurations of <a href="#COM_SAFETY_MODE">COM_SAFETY_MODE</a> and <a href="#COM_PREARM_MODE">COM_PREARM_MODE</a>.</p><h3 id="com-safety-mode-always-off-default-and-com-prearm-mode-disabled-default" tabindex="-1">COM_SAFETY_MODE=Always off (Default) and COM_PREARM_MODE=Disabled (Default) <a class="header-anchor" href="#com-safety-mode-always-off-default-and-com-prearm-mode-disabled-default" aria-label="Permalink to &quot;COM_SAFETY_MODE=Always off (Default) and COM_PREARM_MODE=Disabled (Default)&quot;">​</a></h3><p>The default configuration does not impose any additional safety measures. Arming is possible as soon as the rest of the system is ready.</p><p>Послідовність запуску така:</p><ol><li>Увімкнення живлення. <ul><li>Усі приводи заблоковано у беззбройному(вимкненому) положенні</li><li>System safety is off: Arming possible once the other pre-arm checks pass.</li></ul></li><li>Видається команда на озброєння(збурення). <ul><li>Система озброєна(збурена).</li><li>Усі мотори та приводи можуть рухатися.</li></ul></li></ol><h3 id="com-safety-mode-safety-switch-physical-or-virtual-via-mavlink-and-com-prearm-mode-when-safety-off" tabindex="-1">COM_SAFETY_MODE=Safety switch (physical or virtual via MAVLink) and COM_PREARM_MODE=When safety off <a class="header-anchor" href="#com-safety-mode-safety-switch-physical-or-virtual-via-mavlink-and-com-prearm-mode-when-safety-off" aria-label="Permalink to &quot;COM_SAFETY_MODE=Safety switch (physical or virtual via MAVLink) and COM_PREARM_MODE=When safety off&quot;">​</a></h3><p>This configuration lets you use either the safety switch or a MAVLink command <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_SAFETY_SWITCH_STATE" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_SAFETY_SWITCH_STATE</a> to turn safety off. Note that sending the corresponding MAVLink command with SAFETY<em>SWITCH_STATE_SAFE also lets you turn safety back on, but the physical switch does _not</em> allow to go back to a safe state.</p><p>Послідовність запуску така:</p><ol><li>Увімкнення живлення. <ul><li>Усі приводи заблоковано у беззбройному(вимкненому) положенні</li><li>Неможливо озброїти(збурити).</li></ul></li><li>Safety switch is pressed or a MAVLink command is received. <ul><li>System now pre-armed: non-throttling actuators can move (e.g. ailerons).</li><li>System safety is off: Arming possible once the other pre-arm checks pass.</li></ul></li><li>Видається команда на озброєння(збурення). <ul><li>Система озброєна(збурена).</li><li>Усі мотори та приводи можуть рухатися.</li></ul></li></ol><h3 id="com-safety-mode-physical-safety-switch-only-and-com-prearm-mode-when-safety-off" tabindex="-1">COM_SAFETY_MODE=Physical safety switch only and COM_PREARM_MODE=When safety off <a class="header-anchor" href="#com-safety-mode-physical-safety-switch-only-and-com-prearm-mode-when-safety-off" aria-label="Permalink to &quot;COM_SAFETY_MODE=Physical safety switch only and COM_PREARM_MODE=When safety off&quot;">​</a></h3><p>When safety mode is <code>Physical safety switch only</code>, you must press the safety switch to turn safety off. Note that pressing the safety switch again does <em>not</em> allow to go back to a safe state. The MAVLink command is rejected.</p><p>Послідовність запуску така:</p><ol><li>Увімкнення живлення. <ul><li>Усі приводи заблоковано у беззбройному(вимкненому) положенні</li><li>Неможливо озброїти(збурити).</li></ul></li><li>Перемикання безпеки натиснуто. <ul><li>System now pre-armed: non-throttling actuators can move (e.g. ailerons).</li><li>System safety is off: Arming possible once the other pre-arm checks pass.</li></ul></li><li>Видається команда на озброєння(збурення). <ul><li>Система озброєна(збурена).</li><li>Усі мотори та приводи можуть рухатися.</li></ul></li></ol><h3 id="com-safety-mode-mavlink-only-and-com-prearm-mode-when-safety-off" tabindex="-1">COM_SAFETY_MODE=MAVLink only and COM_PREARM_MODE=When safety off <a class="header-anchor" href="#com-safety-mode-mavlink-only-and-com-prearm-mode-when-safety-off" aria-label="Permalink to &quot;COM_SAFETY_MODE=MAVLink only and COM_PREARM_MODE=When safety off&quot;">​</a></h3><p>When safety mode is <code>MAVLink only</code>, you must send a MAVLink command <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_SAFETY_SWITCH_STATE" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_SAFETY_SWITCH_STATE</a> to turn safety off. Note that sending the corresponding MAVLink command with SAFETY_SWITCH_STATE_SAFE also lets you turn safety back on. Any physical safety switch is ignored.</p><p>Послідовність запуску така:</p><ol><li>Увімкнення живлення. <ul><li>Усі приводи заблоковано у беззбройному(вимкненому) положенні</li><li>Неможливо озброїти(збурити).</li></ul></li><li>A MAVLink command is received. <ul><li>System now pre-armed: non-throttling actuators can move (e.g. ailerons).</li><li>System safety is off: Arming possible once the other pre-arm checks pass.</li></ul></li><li>Видається команда на озброєння(збурення). <ul><li>Система озброєна(збурена).</li><li>Усі мотори та приводи можуть рухатися.</li></ul></li></ol><h3 id="параметри" tabindex="-1">Параметри <a class="header-anchor" href="#параметри" aria-label="Permalink to &quot;Параметри&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="COM_SAFETY_MODE"></a><a href="./../advanced_config/parameter_reference#COM_SAFETY_MODE">COM_SAFETY_MODE</a></td><td>Condition to turn safety off. Vehicle arming is prevented for as long as safety is on.</td></tr><tr><td><a id="COM_PREARM_MODE"></a><a href="./../advanced_config/parameter_reference#COM_PREARM_MODE">COM_PREARM_MODE</a></td><td>Condition to enter the prearmed state.</td></tr></tbody></table>',68)])])}const _=a(i,[["render",s]]);export{f as __pageData,_ as default};
